tool_use_result.content:
/* ===== LearnForge Design System ===== */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #FFFFFF;
  --gray-50: #FAFAFA;
  --gray-100: #F5F5F5;
  --gray-200: #E5E5E5;
  --gray-300: #D4D4D4;
  --gray-400: #A3A3A3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); font-weight: 700; line-height: 1.15; color: var(--black); }

h1 { font-size: clamp(2.25rem, 5vw, 3.75rem); letter-spacing: -0.03em; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.75rem); letter-spacing: -0.02em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); letter-spacing: -0.01em; }
h4 { font-size: 1.125rem; }

p { line-height: 1.7; color: var(--gray-600); }

/* --- Layout --- */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

.section { padding: 80px 0; }
.section--gray { background: var(--gray-100); }
.section--dark { background: var(--black); color: var(--white); }
.section--dark p { color: var(--gray-400); }
.section--dark h2, .section--dark h3 { color: var(--white); }

.section__header { text-align: center; max-width: 720px; margin: 0 auto 48px; }
.section__header p { margin-top: 16px; font-size: 1.125rem; }
.section__label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--burgundy);
  margin-bottom: 12px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: var(--transition);
  white-space: nowrap;
}

.btn--primary {
  background: var(--lime);
  color: var(--black);
}
.btn--primary:hover { background: #d4e62d; transform: translateY(-1px); box-shadow: var(--shadow-lg); }

.btn--secondary {
  background: var(--white);
  color: var(--black);
  border: 1.5px solid var(--gray-300);
}
.btn--secondary:hover { border-color: var(--black); transform: translateY(-1px); }

.btn--dark {
  background: var(--black);
  color: var(--lime);
}
.btn--dark:hover { background: var(--gray-800); transform: translateY(-1px); }

.btn--outline-light {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,0.3);
}
.btn--outline-light:hover { border-color: var(--white); }

.btn--lg { padding: 16px 36px; font-size: 1rem; }
.btn--sm { padding: 10px 20px; font-size: 0.875rem; }

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: var(--transition);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.03em;
}

.nav__logo span { color: var(--lime); background: var(--black); padding: 2px 6px; border-radius: 4px; margin-left: 2px; }

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav__link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: var(--transition);
  position: relative;
}

.nav__link:hover { color: var(--black); }

.nav__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--lime);
  transition: var(--transition);
}

.nav__link:hover::after { width: 100%; }

.nav__cta { margin-left: 8px; }

.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}

.nav__mobile-toggle span {
  width: 24px;
  height: 2px;
  background: var(--black);
  transition: var(--transition);
}

/* Mobile nav */
.nav__mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: 24px;
  flex-direction: column;
  gap: 16px;
  box-shadow: var(--shadow-lg);
}

.nav__mobile-menu.active { display: flex; }

.nav__mobile-menu .nav__link { font-size: 1.125rem; padding: 8px 0; }
.nav__mobile-menu .nav__link::after { display: none; }

@media (max-width: 900px) {
  .nav__links { display: none; }
  .nav__mobile-toggle { display: flex; }
}

/* --- Hero --- */
.hero {
  padding: 140px 0 80px;
  background: var(--black);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero__content { max-width: 800px; position: relative; z-index: 1; }

.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 .highlight { color: var(--lime); }
.hero p { color: var(--gray-400); font-size: 1.1875rem; margin-bottom: 32px; max-width: 600px; }

.hero__actions { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 48px; }

/* Hero Tabs */
.hero__tabs {
  display: flex;
  gap: 4px;
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 24px;
  width: fit-content;
}

.hero__tab {
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-400);
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.hero__tab.active {
  background: var(--lime);
  color: var(--black);
}

.hero__tab:hover:not(.active) { color: var(--white); }

.hero__preview {
  background: var(--gray-900);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  padding: 32px;
  min-height: 260px;
  position: relative;
}

.hero__preview-panel { display: none; }
.hero__preview-panel.active { display: block; }

.hero__preview-panel h3 {
  color: var(--white);
  font-size: 1.125rem;
  margin-bottom: 16px;
}

.hero__preview-panel p { color: var(--gray-400); font-size: 0.9375rem; }

.hero__mock-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 20px;
}

.hero__mock-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-600);
}

.hero__mock-dot:nth-child(1) { background: #ff5f57; }
.hero__mock-dot:nth-child(2) { background: #ffbd2e; }
.hero__mock-dot:nth-child(3) { background: #28ca41; }

.hero__mock-nav {
  display: flex;
  gap: 24px;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  margin-bottom: 20px;
}

.hero__mock-link {
  font-size: 0.8125rem;
  color: var(--gray-400);
}

.hero__mock-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.hero__mock-card {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-sm);
  padding: 16px;
}

.hero__mock-card h4 { color: var(--white); font-size: 0.875rem; margin-bottom: 4px; }
.hero__mock-card p { font-size: 0.75rem; color: var(--gray-500); }

.hero__mock-progress {
  margin-top: 16px;
  background: rgba(255,255,255,0.05);
  border-radius: 4px;
  height: 6px;
  overflow: hidden;
}

.hero__mock-progress-bar {
  height: 100%;
  background: var(--lime);
  border-radius: 4px;
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--lime);
  padding: 32px 0;
}

.stats-bar__grid {
  display: flex;
  justify-content: center;
  gap: 64px;
  flex-wrap: wrap;
}

.stats-bar__item {
  text-align: center;
}

.stats-bar__number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.03em;
}

.stats-bar__label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--gray-700);
  margin-top: 4px;
}

/* --- Product Cards --- */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
  border-color: transparent;
}

.product-card__icon {
  width: 48px;
  height: 48px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.product-card h3 { margin-bottom: 12px; }
.product-card p { font-size: 0.9375rem; }
.product-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--black);
  transition: var(--transition);
}

.product-card__link:hover { gap: 10px; }

@media (max-width: 900px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .products-grid { grid-template-columns: 1fr; }
}

/* --- Why Choose Us Tabs --- */
.tabs {
  display: flex;
  gap: 4px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 40px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.tabs__btn {
  padding: 12px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-500);
  border-radius: var(--radius-sm);
  transition: var(--transition);
  white-space: nowrap;
  flex-shrink: 0;
}

.tabs__btn.active {
  background: var(--white);
  color: var(--black);
  box-shadow: var(--shadow-sm);
}

.tabs__btn:hover:not(.active) { color: var(--gray-700); }

.tabs__panel { display: none; }
.tabs__panel.active { display: block; animation: fadeIn 0.3s ease; }

.feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}

.feature-list__item {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 20px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
}

.feature-list__icon {
  width: 40px;
  height: 40px;
  background: var(--lime);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.125rem;
}

.feature-list__text h4 { margin-bottom: 4px; }
.feature-list__text p { font-size: 0.875rem; }

/* --- Global Scale --- */
.global-scale {
  text-align: center;
}

.global-scale__map {
  max-width: 600px;
  margin: 0 auto 32px;
  font-size: 4rem;
  opacity: 0.15;
}

/* --- AI Section --- */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}

.ai-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.ai-item:hover { border-color: var(--lime); background: rgba(230,255,50,0.05); }

.ai-item__icon { font-size: 1.25rem; }
.ai-item span { font-size: 0.875rem; font-weight: 500; color: var(--gray-300); }

/* --- Testimonials Carousel --- */
.testimonials { position: relative; overflow: hidden; }

.testimonials__track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card {
  min-width: 100%;
  padding: 40px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  flex-shrink: 0;
}

.testimonial-card__quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--gray-700);
  margin-bottom: 24px;
  font-style: italic;
}

.testimonial-card__quote::before { content: '"'; font-size: 2rem; color: var(--lime); font-weight: 800; line-height: 0; vertical-align: -0.3em; margin-right: 4px; }

.testimonial-card__author { display: flex; align-items: center; gap: 16px; }

.testimonial-card__avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
  color: var(--gray-500);
}

.testimonial-card__name { font-weight: 600; color: var(--black); }
.testimonial-card__role { font-size: 0.875rem; color: var(--gray-500); }

.testimonials__controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 24px;
}

.testimonials__btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  font-size: 1.125rem;
  color: var(--gray-500);
}

.testimonials__btn:hover { border-color: var(--black); color: var(--black); background: var(--gray-50); }

.testimonials__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.testimonials__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: var(--transition);
  cursor: pointer;
}

.testimonials__dot.active { background: var(--black); width: 24px; border-radius: 4px; }

/* --- Pricing --- */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  position: relative;
  transition: var(--transition);
}

.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.pricing-card--featured {
  border-color: var(--lime);
  background: var(--black);
}

.pricing-card--featured h3,
.pricing-card--featured .pricing-card__price,
.pricing-card--featured .pricing-card__period { color: var(--white); }

.pricing-card--featured p { color: var(--gray-400); }

.pricing-card--featured .pricing-card__badge {
  background: var(--lime);
  color: var(--black);
}

.pricing-card__badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--lime);
  color: var(--black);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-card h3 { font-size: 1.25rem; margin-bottom: 8px; }
.pricing-card p { font-size: 0.875rem; margin-bottom: 20px; }

.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.03em;
}

.pricing-card__period {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 24px;
}

.pricing-card__features { margin-bottom: 24px; }

.pricing-card__feature {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.875rem;
  color: var(--gray-600);
}

.pricing-card--featured .pricing-card__feature { color: var(--gray-400); }

.pricing-card__check {
  width: 18px;
  height: 18px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  color: var(--black);
  flex-shrink: 0;
}

.pricing-card--featured .pricing-card__check { background: var(--lime); }

@media (max-width: 900px) {
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .pricing-grid { grid-template-columns: 1fr; }
}

/* --- Integrations --- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
}

.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 20px 16px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.integration-item:hover { border-color: var(--gray-400); transform: translateY(-2px); box-shadow: var(--shadow-md); }

.integration-item__icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
}

.integration-item span { font-size: 0.8125rem; font-weight: 500; color: var(--gray-600); }

/* --- FAQ Accordion --- */
.faq-list { max-width: 800px; margin: 0 auto; }

.faq-item {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  transition: var(--transition);
}

.faq-item:hover { border-color: var(--gray-300); }

.faq-item__question {
  width: 100%;
  text-align: left;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--black);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: var(--transition);
}

.faq-item__question:hover { background: var(--gray-50); }

.faq-item__icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  flex-shrink: 0;
  font-size: 1.125rem;
  color: var(--gray-500);
}

.faq-item.active .faq-item__icon { transform: rotate(45deg); background: var(--lime); color: var(--black); }

.faq-item__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}

.faq-item__answer-inner {
  padding: 0 24px 20px;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--gray-600);
}

/* --- CTA Banner --- */
.cta-banner {
  background: var(--black);
  border-radius: var(--radius-xl);
  padding: 64px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(230,255,50,0.2) 0%, transparent 70%);
  pointer-events: none;
}

.cta-banner h2 { color: var(--white); margin-bottom: 16px; position: relative; z-index: 1; }
.cta-banner p { color: var(--gray-400); margin-bottom: 32px; font-size: 1.125rem; position: relative; z-index: 1; }
.cta-banner .btn { position: relative; z-index: 1; }

/* --- Footer --- */
.footer {
  background: var(--gray-900);
  padding: 64px 0 32px;
  color: var(--gray-400);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer__brand p { font-size: 0.9375rem; margin-top: 16px; line-height: 1.7; }

.footer__col h4 {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
}

.footer__link {
  display: block;
  font-size: 0.875rem;
  color: var(--gray-400);
  padding: 6px 0;
  transition: var(--transition);
}

.footer__link:hover { color: var(--white); transform: translateX(4px); }

.footer__bottom {
  border-top: 1px solid var(--gray-700);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
}

@media (max-width: 900px) {
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .footer__brand { grid-column: 1 / -1; }
}

@media (max-width: 600px) {
  .footer__grid { grid-template-columns: 1fr; }
  .footer__bottom { flex-direction: column; gap: 12px; text-align: center; }
}

/* --- Page Hero (Subpages) --- */
.page-hero {
  padding: 140px 0 64px;
  background: var(--black);
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(230,255,50,0.1) 0%, transparent 70%);
  pointer-events: none;
}

.page-hero h1 { color: var(--white); margin-bottom: 16px; position: relative; z-index: 1; }
.page-hero p { color: var(--gray-400); font-size: 1.1875rem; max-width: 600px; position: relative; z-index: 1; }

/* --- Feature Cards --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
}

.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); border-color: transparent; }

.feature-card__icon {
  width: 56px;
  height: 56px;
  background: var(--lime);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.feature-card h3 { margin-bottom: 12px; }
.feature-card p { font-size: 0.9375rem; }

@media (max-width: 900px) {
  .features-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 600px) {
  .features-grid { grid-template-columns: 1fr; }
}

/* --- Steps --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}

.steps-grid::before {
  content: '';
  position: absolute;
  top: 40px;
  left: calc(16.67% + 20px);
  right: calc(16.67% + 20px);
  height: 2px;
  background: var(--gray-200);
}

.step-card {
  text-align: center;
  position: relative;
}

.step-card__number {
  width: 56px;
  height: 56px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--black);
  margin: 0 auto 20px;
  position: relative;
  z-index: 1;
}

.step-card h3 { margin-bottom: 8px; }
.step-card p { font-size: 0.9375rem; }

@media (max-width: 700px) {
  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }
}

/* --- Spotlight Cards --- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
}

.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }

.spotlight-card__tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--burgundy);
  background: rgba(127,42,35,0.08);
  padding: 4px 12px;
  border-radius: 20px;
  margin-bottom: 16px;
}

.spotlight-card h3 { margin-bottom: 8px; }
.spotlight-card p { font-size: 0.9375rem; }

@media (max-width: 700px) {
  .spotlight-grid { grid-template-columns: 1fr; }
}

/* --- Resources --- */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.resource-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.resource-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }

.resource-card__icon {
  font-size: 2rem;
  margin-bottom: 16px;
}

.resource-card h3 { margin-bottom: 8px; font-size: 1.0625rem; }
.resource-card p { font-size: 0.875rem; flex-grow: 1; }
.resource-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: 0.875rem;
  font-weight: 600;
  transition: var(--transition);
}

.resource-card__link:hover { gap: 10px; }

@media (max-width: 700px) {
  .resources-grid { grid-template-columns: 1fr; }
}

/* --- File Types --- */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 16px;
}

.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.file-type-item:hover { background: var(--lime); }

.file-type-item__icon { font-size: 1.25rem; }
.file-type-item span { font-size: 0.875rem; font-weight: 500; }

/* --- Tools Grid --- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 12px;
}

.tools-grid__item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: var(--gray-50);
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  transition: var(--transition);
}

.tools-grid__item:hover { background: var(--lime); }

.tools-grid__icon { font-size: 1rem; }

/* --- Coaching Features (4-col) --- */
.coaching-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

@media (max-width: 700px) {
  .coaching-features-grid { grid-template-columns: 1fr; }
}

/* --- Membership Stats --- */
.membership-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}

.membership-stat {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
}

.membership-stat__number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--lime);
  background: var(--black);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.membership-stat__number--solid {
  color: var(--black);
  -webkit-text-fill-color: var(--black);
}

.membership-stat h4 { margin-top: 8px; margin-bottom: 8px; }
.membership-stat p { font-size: 0.875rem; }

@media (max-width: 700px) {
  .membership-stats { grid-template-columns: 1fr; }
}

/* --- Scroll Animations --- */
.animate {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate.visible {
  opacity: 1;
  transform: translateY(0);
}

/* --- Utilities --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mt-2 { margin-top: 8px; }
.mt-4 { margin-top: 16px; }
.mt-6 { margin-top: 24px; }
.mt-8 { margin-top: 32px; }
.mb-0 { margin-bottom: 0; }
.mb-2 { margin-bottom: 8px; }
.mb-4 { margin-bottom: 16px; }
.mb-6 { margin-bottom: 24px; }
.mb-8 { margin-bottom: 32px; }

/* --- Product Demo Accordion --- */
.demo-accordion {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.demo-accordion__toggle {
  width: 100%;
  text-align: left;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--black);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--gray-50);
  transition: var(--transition);
}

.demo-accordion__toggle:hover { background: var(--gray-100); }

.demo-accordion__icon {
  transition: var(--transition);
  font-size: 1.25rem;
  color: var(--gray-500);
}

.demo-accordion.active .demo-accordion__icon { transform: rotate(180deg); }

.demo-accordion__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.demo-accordion__content-inner {
  padding: 32px;
  background: var(--gray-900);
  color: var(--white);
}

.demo-accordion__content-inner h3 { color: var(--white); margin-bottom: 12px; }
.demo-accordion__content-inner p { color: var(--gray-400); }

/* --- Business Fit --- */
.business-fit-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

@media (max-width: 700px) {
  .business-fit-grid { grid-template-columns: 1fr; }
}

/* --- Social proof section --- */
.social-proof {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  text-align: center;
}

.social-proof__item {
  padding: 24px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
}

.social-proof__item h4 { color: var(--burgundy); font-size: 1.5rem; margin-bottom: 8px; }
.social-proof__item p { font-size: 0.875rem; }

@media (max-width: 700px) {
  .social-proof { grid-template-columns: 1fr; }
}

/* --- Value Proposition Cards (with number) --- */
.value-prop-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.value-prop-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  transition: var(--transition);
}

.value-prop-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }

.value-prop-card__number {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 800;
  color: var(--lime);
  opacity: 0.4;
  position: absolute;
  top: 16px;
  right: 24px;
}

.value-prop-card h3 { margin-bottom: 12px; }
.value-prop-card p { font-size: 0.9375rem; }

@media (max-width: 700px) {
  .value-prop-grid { grid-template-columns: 1fr; }
}

/* --- Create and Sell (split layout) --- */
.split-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.split-layout__content h2 { margin-bottom: 16px; }
.split-layout__content p { margin-bottom: 12px; }

.split-layout__visual {
  background: var(--gray-900);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
}

@media (max-width: 900px) {
  .split-layout { grid-template-columns: 1fr; }
}

/* --- Pricing overview (memberships page) --- */
.pricing-overview {
  background: var(--gray-100);
  border-radius: var(--radius-xl);
  padding: 48px;
  text-align: center;
}

.pricing-overview__tiers {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 32px;
}

.pricing-overview__tier {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  transition: var(--transition);
}

.pricing-overview__tier:hover { box-shadow: var(--shadow-lg); }

.pricing-overview__tier h4 { margin-bottom: 4px; }
.pricing-overview__tier .price { font-family: var(--font-heading); font-size: 1.75rem; font-weight: 800; color: var(--black); }
.pricing-overview__tier .period { font-size: 0.8125rem; color: var(--gray-500); }

@media (max-width: 900px) {
  .pricing-overview__tiers { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .pricing-overview__tiers { grid-template-columns: 1fr; }
  .pricing-overview { padding: 32px 16px; }
}

/* ===== LearnForge Design System ===== */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #FFFFFF;
  --gray-50: #FAFAFA;
  --gray-100: #F5F5F5;
  --gray-200: #E5E5E5;
  --gray-300: #D4D4D4;
  --gray-400: #A3A3A3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); font-weight: 700; line-height: 1.15; color: var(--black); }

h1 { font-size: clamp(2.25rem, 5vw, 3.75rem); letter-spacing: -0.03em; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.75rem); letter-spacing: -0.02em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); letter-spacing: -0.01em; }
h4 { font-size: 1.125rem; }

p { line-height: 1.7; color: var(--gray-600); }

/* --- Layout --- */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

.section { padding: 80px 0; }
.section--gray { background: var(--gray-100); }
.section--dark { background: var(--black); color: var(--white); }
.section--dark p { color: var(--gray-400); }
.section--dark h2, .section--dark h3 { color: var(--white); }

.section__header { text-align: center; max-width: 720px; margin: 0 auto 48px; }
.section__header p { margin-top: 16px; font-size: 1.125rem; }
.section__label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--burgundy);
  margin-bottom: 12px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: var(--transition);
  white-space: nowrap;
}

.btn--primary {
  background: var(--lime);
  color: var(--black);
}
.btn--primary:hover { background: #d4e62d; transform: translateY(-1px); box-shadow: var(--shadow-lg); }

.btn--secondary {
  background: var(--white);
  color: var(--black);
  border: 1.5px solid var(--gray-300);
}
.btn--secondary:hover { border-color: var(--black); transform: translateY(-1px); }

.btn--dark {
  background: var(--black);
  color: var(--lime);
}
.btn--dark:hover { background: var(--gray-800); transform: translateY(-1px); }

.btn--outline-light {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,0.3);
}
.btn--outline-light:hover { border-color: var(--white); }

.btn--lg { padding: 16px 36px; font-size: 1rem; }
.btn--sm { padding: 10px 20px; font-size: 0.875rem; }

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: var(--transition);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.03em;
}

.nav__logo span { color: var(--lime); background: var(--black); padding: 2px 6px; border-radius: 4px; margin-left: 2px; }

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav__link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: var(--transition);
  position: relative;
}

.nav__link:hover { color: var(--black); }

.nav__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--lime);
  transition: var(--transition);
}

.nav__link:hover::after { width: 100%; }

.nav__cta { margin-left: 8px; }

.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}

.nav__mobile-toggle span {
  width: 24px;
  height: 2px;
  background: var(--black);
  transition: var(--transition);
}

/* Mobile nav */
.nav__mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: 24px;
  flex-direction: column;
  gap: 16px;
  box-shadow: var(--shadow-lg);
}

.nav__mobile-menu.active { display: flex; }

.nav__mobile-menu .nav__link { font-size: 1.125rem; padding: 8px 0; }
.nav__mobile-menu .nav__link::after { display: none; }

@media (max-width: 900px) {
  .nav__links { display: none; }
  .nav__mobile-toggle { display: flex; }
}

/* --- Hero --- */
.hero {
  padding: 140px 0 80px;
  background: var(--black);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero__content { max-width: 800px; position: relative; z-index: 1; }

.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 .highlight { color: var(--lime); }
.hero p { color: var(--gray-400); font-size: 1.1875rem; margin-bottom: 32px; max-width: 600px; }

.hero__actions { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 48px; }

/* Hero Tabs */
.hero__tabs {
  display: flex;
  gap: 4px;
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 24px;
  width: fit-content;
}

.hero__tab {
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-400);
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.hero__tab.active {
  background: var(--lime);
  color: var(--black);
}

.hero__tab:hover:not(.active) { color: var(--white); }

.hero__preview {
  background: var(--gray-900);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  padding: 32px;
  min-height: 260px;
  position: relative;
}

.hero__preview-panel { display: none; }
.hero__preview-panel.active { display: block; }

.hero__preview-panel h3 {
  color: var(--white);
  font-size: 1.125rem;
  margin-bottom: 16px;
}

.hero__preview-panel p { color: var(--gray-400); font-size: 0.9375rem; }

.hero__mock-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 20px;
}

.hero__mock-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-600);
}

.hero__mock-dot:nth-child(1) { background: #ff5f57; }
.hero__mock-dot:nth-child(2) { background: #ffbd2e; }
.hero__mock-dot:nth-child(3) { background: #28ca41; }

.hero__mock-nav {
  display: flex;
  gap: 24px;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  margin-bottom: 20px;
}

.hero__mock-link {
  font-size: 0.8125rem;
  color: var(--gray-400);
}

.hero__mock-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.hero__mock-card {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-sm);
  padding: 16px;
}

.hero__mock-card h4 { color: var(--white); font-size: 0.875rem; margin-bottom: 4px; }
.hero__mock-card p { font-size: 0.75rem; color: var(--gray-500); }

.hero__mock-progress {
  margin-top: 16px;
  background: rgba(255,255,255,0.05);
  border-radius: 4px;
  height: 6px;
  overflow: hidden;
}

.hero__mock-progress-bar {
  height: 100%;
  background: var(--lime);
  border-radius: 4px;
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--lime);
  padding: 32px 0;
}

.stats-bar__grid {
  display: flex;
  justify-content: center;
  gap: 64px;
  flex-wrap: wrap;
}

.stats-bar__item {
  text-align: center;
}

.stats-bar__number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.03em;
}

.stats-bar__label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--gray-700);
  margin-top: 4px;
}

/* --- Product Cards --- */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
  border-color: transparent;
}

.product-card__icon {
  width: 48px;
  height: 48px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.product-card h3 { margin-bottom: 12px; }
.product-card p { font-size: 0.9375rem; }
.product-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--black);
  transition: var(--transition);
}

.product-card__link:hover { gap: 10px; }

@media (max-width: 900px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .products-grid { grid-template-columns: 1fr; }
}

/* --- Why Choose Us Tabs --- */
.tabs {
  display: flex;
  gap: 4px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 40px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.tabs__btn {
  padding: 12px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-500);
  border-radius: var(--radius-sm);
  transition: var(--transition);
  white-space: nowrap;
  flex-shrink: 0;
}

.tabs__btn.active {
  background: var(--white);
  color: var(--black);
  box-shadow: var(--shadow-sm);
}

.tabs__btn:hover:not(.active) { color: var(--gray-700); }

.tabs__panel { display: none; }
.tabs__panel.active { display: block; animation: fadeIn 0.3s ease; }

.feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}

.feature-list__item {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 20px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
}

.feature-list__icon {
  width: 40px;
  height: 40px;
  background: var(--lime);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.125rem;
}

.feature-list__text h4 { margin-bottom: 4px; }
.feature-list__text p { font-size: 0.875rem; }

/* --- Global Scale --- */
.global-scale {
  text-align: center;
}

.global-scale__map {
  max-width: 600px;
  margin: 0 auto 32px;
  font-size: 4rem;
  opacity: 0.15;
}

/* --- AI Section --- */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}

.ai-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.ai-item:hover { border-color: var(--lime); background: rgba(230,255,50,0.05); }

.ai-item__icon { font-size: 1.25rem; }
.ai-item span { font-size: 0.875rem; font-weight: 500; color: var(--gray-300); }

/* --- Testimonials Carousel --- */
.testimonials { position: relative; overflow: hidden; }

.testimonials__track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card {
  min-width: 100%;
  padding: 40px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  flex-shrink: 0;
}

.testimonial-card__quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--gray-700);
  margin-bottom: 24px;
  font-style: italic;
}

.testimonial-card__quote::before { content: '"'; font-size: 2rem; color: var(--lime); font-weight: 800; line-height: 0; vertical-align: -0.3em; margin-right: 4px; }

.testimonial-card__author { display: flex; align-items: center; gap: 16px; }

.testimonial-card__avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
  color: var(--gray-500);
}

.testimonial-card__name { font-weight: 600; color: var(--black); }
.testimonial-card__role { font-size: 0.875rem; color: var(--gray-500); }

.testimonials__controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 24px;
}

.testimonials__btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  font-size: 1.125rem;
  color: var(--gray-500);
}

.testimonials__btn:hover { border-color: var(--black); color: var(--black); background: var(--gray-50); }

.testimonials__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.testimonials__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: var(--transition);
  cursor: pointer;
}

.testimonials__dot.active { background: var(--black); width: 24px; border-radius: 4px; }

/* --- Pricing --- */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  position: relative;
  transition: var(--transition);
}

.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.pricing-card--featured {
  border-color: var(--lime);
  background: var(--black);
}

.pricing-card--featured h3,
.pricing-card--featured .pricing-card__price,
.pricing-card--featured .pricing-card__period { color: var(--white); }

.pricing-card--featured p { color: var(--gray-400); }

.pricing-card--featured .pricing-card__badge {
  background: var(--lime);
  color: var(--black);
}

.pricing-card__badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--lime);
  color: var(--black);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-card h3 { font-size: 1.25rem; margin-bottom: 8px; }
.pricing-card p { font-size: 0.875rem; margin-bottom: 20px; }

.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.03em;
}

.pricing-card__period {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 24px;
}

.pricing-card__features { margin-bottom: 24px; }

.pricing-card__feature {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.875rem;
  color: var(--gray-600);
}

.pricing-card--featured .pricing-card__feature { color: var(--gray-400); }

.pricing-card__check {
  width: 18px;
  height: 18px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  color: var(--black);
  flex-shrink: 0;
}

.pricing-card--featured .pricing-card__check { background: var(--lime); }

@media (max-width: 900px) {
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .pricing-grid { grid-template-columns: 1fr; }
}

/* --- Integrations --- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
}

.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 20px 16px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.integration-item:hover { border-color: var(--gray-400); transform: translateY(-2px); box-shadow: var(--shadow-md); }

.integration-item__icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
}

.integration-item span { font-size: 0.8125rem; font-weight: 500; color: var(--gray-600); }

/* --- FAQ Accordion --- */
.faq-list { max-width: 800px; margin: 0 auto; }

.faq-item {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  transition: var(--transition);
}

.faq-item:hover { border-color: var(--gray-300); }

.faq-item__question {
  width: 100%;
  text-align: left;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--black);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: var(--transition);
}

.faq-item__question:hover { background: var(--gray-50); }

.faq-item__icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  flex-shrink: 0;
  font-size: 1.125rem;
  color: var(--gray-500);
}

.faq-item.active .faq-item__icon { transform: rotate(45deg); background: var(--lime); color: var(--black); }

.faq-item__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}

.faq-item__answer-inner {
  padding: 0 24px 20px;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--gray-600);
}

/* --- CTA Banner --- */
.cta-banner {
  background: var(--black);
  border-radius: var(--radius-xl);
  padding: 64px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(230,255,50,0.2) 0%, transparent 70%);
  pointer-events: none;
}

.cta-banner h2 { color: var(--white); margin-bottom: 16px; position: relative; z-index: 1; }
.cta-banner p { color: var(--gray-400); margin-bottom: 32px; font-size: 1.125rem; position: relative; z-index: 1; }
.cta-banner .btn { position: relative; z-index: 1; }

/* --- Footer --- */
.footer {
  background: var(--gray-900);
  padding: 64px 0 32px;
  color: var(--gray-400);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer__brand p { font-size: 0.9375rem; margin-top: 16px; line-height: 1.7; }

.footer__col h4 {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
}

.footer__link {
  display: block;
  font-size: 0.875rem;
  color: var(--gray-400);
  padding: 6px 0;
  transition: var(--transition);
}

.footer__link:hover { color: var(--white); transform: translateX(4px); }

.footer__bottom {
  border-top: 1px solid var(--gray-700);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
}

@media (max-width: 900px) {
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .footer__brand { grid-column: 1 / -1; }
}

@media (max-width: 600px) {
  .footer__grid { grid-template-columns: 1fr; }
  .footer__bottom { flex-direction: column; gap: 12px; text-align: center; }
}

/* --- Page Hero (Subpages) --- */
.page-hero {
  padding: 140px 0 64px;
  background: var(--black);
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(230,255,50,0.1) 0%, transparent 70%);
  pointer-events: none;
}

.page-hero h1 { color: var(--white); margin-bottom: 16px; position: relative; z-index: 1; }
.page-hero p { color: var(--gray-400); font-size: 1.1875rem; max-width: 600px; position: relative; z-index: 1; }

/* --- Feature Cards --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
}

.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); border-color: transparent; }

.feature-card__icon {
  width: 56px;
  height: 56px;
  background: var(--lime);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.feature-card h3 { margin-bottom: 12px; }
.feature-card p { font-size: 0.9375rem; }

@media (max-width: 900px) {
  .features-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 600px) {
  .features-grid { grid-template-columns: 1fr; }
}

/* --- Steps --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}

.steps-grid::before {
  content: '';
  position: absolute;
  top: 40px;
  left: calc(16.67% + 20px);
  right: calc(16.67% + 20px);
  height: 2px;
  background: var(--gray-200);
}

.step-card {
  text-align: center;
  position: relative;
}

.step-card__number {
  width: 56px;
  height: 56px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--black);
  margin: 0 auto 20px;
  position: relative;
  z-index: 1;
}

.step-card h3 { margin-bottom: 8px; }
.step-card p { font-size: 0.9375rem; }

@media (max-width: 700px) {
  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }
}

/* --- Spotlight Cards --- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
}

.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }

.spotlight-card__tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--burgundy);
  background: rgba(127,42,35,0.08);
  padding: 4px 12px;
  border-radius: 20px;
  margin-bottom: 16px;
}

.spotlight-card h3 { margin-bottom: 8px; }
.spotlight-card p { font-size: 0.9375rem; }

@media (max-width: 700px) {
  .spotlight-grid { grid-template-columns: 1fr; }
}

/* --- Resources --- */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.resource-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.resource-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }

.resource-card__icon {
  font-size: 2rem;
  margin-bottom: 16px;
}

.resource-card h3 { margin-bottom: 8px; font-size: 1.0625rem; }
.resource-card p { font-size: 0.875rem; flex-grow: 1; }
.resource-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: 0.875rem;
  font-weight: 600;
  transition: var(--transition);
}

.resource-card__link:hover { gap: 10px; }

@media (max-width: 700px) {
  .resources-grid { grid-template-columns: 1fr; }
}

/* --- File Types --- */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 16px;
}

.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.file-type-item:hover { background: var(--lime); }

.file-type-item__icon { font-size: 1.25rem; }
.file-type-item span { font-size: 0.875rem; font-weight: 500; }

/* --- Tools Grid --- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 12px;
}

.tools-grid__item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: var(--gray-50);
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  transition: var(--transition);
}

.tools-grid__item:hover { background: var(--lime); }

.tools-grid__icon { font-size: 1rem; }

/* --- Coaching Features (4-col) --- */
.coaching-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

@media (max-width: 700px) {
  .coaching-features-grid { grid-template-columns: 1fr; }
}

/* --- Membership Stats --- */
.membership-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}

.membership-stat {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
}

.membership-stat__number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--lime);
  background: var(--black);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.membership-stat__number--solid {
  color: var(--black);
  -webkit-text-fill-color: var(--black);
}

.membership-stat h4 { margin-top: 8px; margin-bottom: 8px; }
.membership-stat p { font-size: 0.875rem; }

@media (max-width: 700px) {
  .membership-stats { grid-template-columns: 1fr; }
}

/* --- Scroll Animations --- */
.animate {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate.visible {
  opacity: 1;
  transform: translateY(0);
}

/* --- Utilities --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mt-2 { margin-top: 8px; }
.mt-4 { margin-top: 16px; }
.mt-6 { margin-top: 24px; }
.mt-8 { margin-top: 32px; }
.mb-0 { margin-bottom: 0; }
.mb-2 { margin-bottom: 8px; }
.mb-4 { margin-bottom: 16px; }
.mb-6 { margin-bottom: 24px; }
.mb-8 { margin-bottom: 32px; }

/* --- Product Demo Accordion --- */
.demo-accordion {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.demo-accordion__toggle {
  width: 100%;
  text-align: left;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--black);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--gray-50);
  transition: var(--transition);
}

.demo-accordion__toggle:hover { background: var(--gray-100); }

.demo-accordion__icon {
  transition: var(--transition);
  font-size: 1.25rem;
  color: var(--gray-500);
}

.demo-accordion.active .demo-accordion__icon { transform: rotate(180deg); }

.demo-accordion__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.demo-accordion__content-inner {
  padding: 32px;
  background: var(--gray-900);
  color: var(--white);
}

.demo-accordion__content-inner h3 { color: var(--white); margin-bottom: 12px; }
.demo-accordion__content-inner p { color: var(--gray-400); }

/* --- Business Fit --- */
.business-fit-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

@media (max-width: 700px) {
  .business-fit-grid { grid-template-columns: 1fr; }
}

/* --- Social proof section --- */
.social-proof {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  text-align: center;
}

.social-proof__item {
  padding: 24px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
}

.social-proof__item h4 { color: var(--burgundy); font-size: 1.5rem; margin-bottom: 8px; }
.social-proof__item p { font-size: 0.875rem; }

@media (max-width: 700px) {
  .social-proof { grid-template-columns: 1fr; }
}

/* --- Value Proposition Cards (with number) --- */
.value-prop-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.value-prop-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  transition: var(--transition);
}

.value-prop-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }

.value-prop-card__number {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 800;
  color: var(--lime);
  opacity: 0.4;
  position: absolute;
  top: 16px;
  right: 24px;
}

.value-prop-card h3 { margin-bottom: 12px; }
.value-prop-card p { font-size: 0.9375rem; }

@media (max-width: 700px) {
  .value-prop-grid { grid-template-columns: 1fr; }
}

/* --- Create and Sell (split layout) --- */
.split-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.split-layout__content h2 { margin-bottom: 16px; }
.split-layout__content p { margin-bottom: 12px; }

.split-layout__visual {
  background: var(--gray-900);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
}

@media (max-width: 900px) {
  .split-layout { grid-template-columns: 1fr; }
}

/* --- Pricing overview (memberships page) --- */
.pricing-overview {
  background: var(--gray-100);
  border-radius: var(--radius-xl);
  padding: 48px;
  text-align: center;
}

.pricing-overview__tiers {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 32px;
}

.pricing-overview__tier {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  transition: var(--transition);
}

.pricing-overview__tier:hover { box-shadow: var(--shadow-lg); }

.pricing-overview__tier h4 { margin-bottom: 4px; }
.pricing-overview__tier .price { font-family: var(--font-heading); font-size: 1.75rem; font-weight: 800; color: var(--black); }
.pricing-overview__tier .period { font-size: 0.8125rem; color: var(--gray-500); }

@media (max-width: 900px) {
  .pricing-overview__tiers { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .pricing-overview__tiers { grid-template-columns: 1fr; }
  .pricing-overview { padding: 32px 16px; }
}

raw_arguments.content:
/* ===== LearnForge Design System ===== */

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --black: #000000;
  --lime: #E6FF32;
  --burgundy: #7F2A23;
  --white: #FFFFFF;
  --gray-50: #FAFAFA;
  --gray-100: #F5F5F5;
  --gray-200: #E5E5E5;
  --gray-300: #D4D4D4;
  --gray-400: #A3A3A3;
  --gray-500: #737373;
  --gray-600: #525252;
  --gray-700: #404040;
  --gray-800: #262626;
  --gray-900: #171717;
  --font-heading: 'Plus Jakarta Sans', 'Inter', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --shadow-sm: 0 1px 2px rgba(0,0,0,0.05);
  --shadow-md: 0 4px 6px -1px rgba(0,0,0,0.07), 0 2px 4px -2px rgba(0,0,0,0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0,0,0,0.08), 0 4px 6px -4px rgba(0,0,0,0.04);
  --shadow-xl: 0 20px 25px -5px rgba(0,0,0,0.08), 0 8px 10px -6px rgba(0,0,0,0.04);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

html { scroll-behavior: smooth; font-size: 16px; }

body {
  font-family: var(--font-body);
  color: var(--gray-800);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul { list-style: none; }
button { cursor: pointer; font-family: inherit; border: none; background: none; }

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 { font-family: var(--font-heading); font-weight: 700; line-height: 1.15; color: var(--black); }

h1 { font-size: clamp(2.25rem, 5vw, 3.75rem); letter-spacing: -0.03em; }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.75rem); letter-spacing: -0.02em; }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); letter-spacing: -0.01em; }
h4 { font-size: 1.125rem; }

p { line-height: 1.7; color: var(--gray-600); }

/* --- Layout --- */
.container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }

.section { padding: 80px 0; }
.section--gray { background: var(--gray-100); }
.section--dark { background: var(--black); color: var(--white); }
.section--dark p { color: var(--gray-400); }
.section--dark h2, .section--dark h3 { color: var(--white); }

.section__header { text-align: center; max-width: 720px; margin: 0 auto 48px; }
.section__header p { margin-top: 16px; font-size: 1.125rem; }
.section__label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--burgundy);
  margin-bottom: 12px;
}

/* --- Buttons --- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.9375rem;
  font-weight: 600;
  border-radius: var(--radius-md);
  transition: var(--transition);
  white-space: nowrap;
}

.btn--primary {
  background: var(--lime);
  color: var(--black);
}
.btn--primary:hover { background: #d4e62d; transform: translateY(-1px); box-shadow: var(--shadow-lg); }

.btn--secondary {
  background: var(--white);
  color: var(--black);
  border: 1.5px solid var(--gray-300);
}
.btn--secondary:hover { border-color: var(--black); transform: translateY(-1px); }

.btn--dark {
  background: var(--black);
  color: var(--lime);
}
.btn--dark:hover { background: var(--gray-800); transform: translateY(-1px); }

.btn--outline-light {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,0.3);
}
.btn--outline-light:hover { border-color: var(--white); }

.btn--lg { padding: 16px 36px; font-size: 1rem; }
.btn--sm { padding: 10px 20px; font-size: 0.875rem; }

/* --- Navigation --- */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 1000;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--gray-200);
  transition: var(--transition);
}

.nav__inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 72px;
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

.nav__logo {
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.03em;
}

.nav__logo span { color: var(--lime); background: var(--black); padding: 2px 6px; border-radius: 4px; margin-left: 2px; }

.nav__links {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav__link {
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--gray-600);
  transition: var(--transition);
  position: relative;
}

.nav__link:hover { color: var(--black); }

.nav__link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--lime);
  transition: var(--transition);
}

.nav__link:hover::after { width: 100%; }

.nav__cta { margin-left: 8px; }

.nav__mobile-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 4px;
}

.nav__mobile-toggle span {
  width: 24px;
  height: 2px;
  background: var(--black);
  transition: var(--transition);
}

/* Mobile nav */
.nav__mobile-menu {
  display: none;
  position: fixed;
  top: 72px;
  left: 0;
  right: 0;
  background: var(--white);
  border-bottom: 1px solid var(--gray-200);
  padding: 24px;
  flex-direction: column;
  gap: 16px;
  box-shadow: var(--shadow-lg);
}

.nav__mobile-menu.active { display: flex; }

.nav__mobile-menu .nav__link { font-size: 1.125rem; padding: 8px 0; }
.nav__mobile-menu .nav__link::after { display: none; }

@media (max-width: 900px) {
  .nav__links { display: none; }
  .nav__mobile-toggle { display: flex; }
}

/* --- Hero --- */
.hero {
  padding: 140px 0 80px;
  background: var(--black);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(230,255,50,0.15) 0%, transparent 70%);
  pointer-events: none;
}

.hero__content { max-width: 800px; position: relative; z-index: 1; }

.hero h1 { color: var(--white); margin-bottom: 20px; }
.hero h1 .highlight { color: var(--lime); }
.hero p { color: var(--gray-400); font-size: 1.1875rem; margin-bottom: 32px; max-width: 600px; }

.hero__actions { display: flex; gap: 12px; flex-wrap: wrap; margin-bottom: 48px; }

/* Hero Tabs */
.hero__tabs {
  display: flex;
  gap: 4px;
  background: rgba(255,255,255,0.1);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 24px;
  width: fit-content;
}

.hero__tab {
  padding: 10px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-400);
  border-radius: var(--radius-sm);
  transition: var(--transition);
}

.hero__tab.active {
  background: var(--lime);
  color: var(--black);
}

.hero__tab:hover:not(.active) { color: var(--white); }

.hero__preview {
  background: var(--gray-900);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-lg);
  padding: 32px;
  min-height: 260px;
  position: relative;
}

.hero__preview-panel { display: none; }
.hero__preview-panel.active { display: block; }

.hero__preview-panel h3 {
  color: var(--white);
  font-size: 1.125rem;
  margin-bottom: 16px;
}

.hero__preview-panel p { color: var(--gray-400); font-size: 0.9375rem; }

.hero__mock-bar {
  display: flex;
  gap: 6px;
  margin-bottom: 20px;
}

.hero__mock-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-600);
}

.hero__mock-dot:nth-child(1) { background: #ff5f57; }
.hero__mock-dot:nth-child(2) { background: #ffbd2e; }
.hero__mock-dot:nth-child(3) { background: #28ca41; }

.hero__mock-nav {
  display: flex;
  gap: 24px;
  padding: 12px 0;
  border-bottom: 1px solid rgba(255,255,255,0.1);
  margin-bottom: 20px;
}

.hero__mock-link {
  font-size: 0.8125rem;
  color: var(--gray-400);
}

.hero__mock-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}

.hero__mock-card {
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-sm);
  padding: 16px;
}

.hero__mock-card h4 { color: var(--white); font-size: 0.875rem; margin-bottom: 4px; }
.hero__mock-card p { font-size: 0.75rem; color: var(--gray-500); }

.hero__mock-progress {
  margin-top: 16px;
  background: rgba(255,255,255,0.05);
  border-radius: 4px;
  height: 6px;
  overflow: hidden;
}

.hero__mock-progress-bar {
  height: 100%;
  background: var(--lime);
  border-radius: 4px;
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--lime);
  padding: 32px 0;
}

.stats-bar__grid {
  display: flex;
  justify-content: center;
  gap: 64px;
  flex-wrap: wrap;
}

.stats-bar__item {
  text-align: center;
}

.stats-bar__number {
  font-family: var(--font-heading);
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.03em;
}

.stats-bar__label {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--gray-700);
  margin-top: 4px;
}

/* --- Product Cards --- */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.product-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  transition: var(--transition);
  position: relative;
  overflow: hidden;
}

.product-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
  border-color: transparent;
}

.product-card__icon {
  width: 48px;
  height: 48px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.product-card h3 { margin-bottom: 12px; }
.product-card p { font-size: 0.9375rem; }
.product-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--black);
  transition: var(--transition);
}

.product-card__link:hover { gap: 10px; }

@media (max-width: 900px) {
  .products-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .products-grid { grid-template-columns: 1fr; }
}

/* --- Why Choose Us Tabs --- */
.tabs {
  display: flex;
  gap: 4px;
  background: var(--gray-100);
  border-radius: var(--radius-md);
  padding: 4px;
  margin-bottom: 40px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.tabs__btn {
  padding: 12px 20px;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-500);
  border-radius: var(--radius-sm);
  transition: var(--transition);
  white-space: nowrap;
  flex-shrink: 0;
}

.tabs__btn.active {
  background: var(--white);
  color: var(--black);
  box-shadow: var(--shadow-sm);
}

.tabs__btn:hover:not(.active) { color: var(--gray-700); }

.tabs__panel { display: none; }
.tabs__panel.active { display: block; animation: fadeIn 0.3s ease; }

.feature-list {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 24px;
}

.feature-list__item {
  display: flex;
  gap: 16px;
  align-items: flex-start;
  padding: 20px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
}

.feature-list__icon {
  width: 40px;
  height: 40px;
  background: var(--lime);
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-size: 1.125rem;
}

.feature-list__text h4 { margin-bottom: 4px; }
.feature-list__text p { font-size: 0.875rem; }

/* --- Global Scale --- */
.global-scale {
  text-align: center;
}

.global-scale__map {
  max-width: 600px;
  margin: 0 auto 32px;
  font-size: 4rem;
  opacity: 0.15;
}

/* --- AI Section --- */
.ai-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 16px;
}

.ai-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.ai-item:hover { border-color: var(--lime); background: rgba(230,255,50,0.05); }

.ai-item__icon { font-size: 1.25rem; }
.ai-item span { font-size: 0.875rem; font-weight: 500; color: var(--gray-300); }

/* --- Testimonials Carousel --- */
.testimonials { position: relative; overflow: hidden; }

.testimonials__track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card {
  min-width: 100%;
  padding: 40px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  flex-shrink: 0;
}

.testimonial-card__quote {
  font-size: 1.125rem;
  line-height: 1.7;
  color: var(--gray-700);
  margin-bottom: 24px;
  font-style: italic;
}

.testimonial-card__quote::before { content: '"'; font-size: 2rem; color: var(--lime); font-weight: 800; line-height: 0; vertical-align: -0.3em; margin-right: 4px; }

.testimonial-card__author { display: flex; align-items: center; gap: 16px; }

.testimonial-card__avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 1rem;
  color: var(--gray-500);
}

.testimonial-card__name { font-weight: 600; color: var(--black); }
.testimonial-card__role { font-size: 0.875rem; color: var(--gray-500); }

.testimonials__controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 24px;
}

.testimonials__btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 1.5px solid var(--gray-300);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  font-size: 1.125rem;
  color: var(--gray-500);
}

.testimonials__btn:hover { border-color: var(--black); color: var(--black); background: var(--gray-50); }

.testimonials__dots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 16px;
}

.testimonials__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-300);
  transition: var(--transition);
  cursor: pointer;
}

.testimonials__dot.active { background: var(--black); width: 24px; border-radius: 4px; }

/* --- Pricing --- */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.pricing-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px 24px;
  position: relative;
  transition: var(--transition);
}

.pricing-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-xl);
}

.pricing-card--featured {
  border-color: var(--lime);
  background: var(--black);
}

.pricing-card--featured h3,
.pricing-card--featured .pricing-card__price,
.pricing-card--featured .pricing-card__period { color: var(--white); }

.pricing-card--featured p { color: var(--gray-400); }

.pricing-card--featured .pricing-card__badge {
  background: var(--lime);
  color: var(--black);
}

.pricing-card__badge {
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--lime);
  color: var(--black);
  font-size: 0.75rem;
  font-weight: 700;
  padding: 4px 16px;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.pricing-card h3 { font-size: 1.25rem; margin-bottom: 8px; }
.pricing-card p { font-size: 0.875rem; margin-bottom: 20px; }

.pricing-card__price {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--black);
  letter-spacing: -0.03em;
}

.pricing-card__period {
  font-size: 0.875rem;
  color: var(--gray-500);
  margin-bottom: 24px;
}

.pricing-card__features { margin-bottom: 24px; }

.pricing-card__feature {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 0;
  font-size: 0.875rem;
  color: var(--gray-600);
}

.pricing-card--featured .pricing-card__feature { color: var(--gray-400); }

.pricing-card__check {
  width: 18px;
  height: 18px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.625rem;
  color: var(--black);
  flex-shrink: 0;
}

.pricing-card--featured .pricing-card__check { background: var(--lime); }

@media (max-width: 900px) {
  .pricing-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .pricing-grid { grid-template-columns: 1fr; }
}

/* --- Integrations --- */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(140px, 1fr));
  gap: 16px;
}

.integration-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 20px 16px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.integration-item:hover { border-color: var(--gray-400); transform: translateY(-2px); box-shadow: var(--shadow-md); }

.integration-item__icon {
  width: 40px;
  height: 40px;
  border-radius: var(--radius-sm);
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
}

.integration-item span { font-size: 0.8125rem; font-weight: 500; color: var(--gray-600); }

/* --- FAQ Accordion --- */
.faq-list { max-width: 800px; margin: 0 auto; }

.faq-item {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-md);
  margin-bottom: 12px;
  overflow: hidden;
  transition: var(--transition);
}

.faq-item:hover { border-color: var(--gray-300); }

.faq-item__question {
  width: 100%;
  text-align: left;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--black);
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  transition: var(--transition);
}

.faq-item__question:hover { background: var(--gray-50); }

.faq-item__icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
  flex-shrink: 0;
  font-size: 1.125rem;
  color: var(--gray-500);
}

.faq-item.active .faq-item__icon { transform: rotate(45deg); background: var(--lime); color: var(--black); }

.faq-item__answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}

.faq-item__answer-inner {
  padding: 0 24px 20px;
  font-size: 0.9375rem;
  line-height: 1.7;
  color: var(--gray-600);
}

/* --- CTA Banner --- */
.cta-banner {
  background: var(--black);
  border-radius: var(--radius-xl);
  padding: 64px 48px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(230,255,50,0.2) 0%, transparent 70%);
  pointer-events: none;
}

.cta-banner h2 { color: var(--white); margin-bottom: 16px; position: relative; z-index: 1; }
.cta-banner p { color: var(--gray-400); margin-bottom: 32px; font-size: 1.125rem; position: relative; z-index: 1; }
.cta-banner .btn { position: relative; z-index: 1; }

/* --- Footer --- */
.footer {
  background: var(--gray-900);
  padding: 64px 0 32px;
  color: var(--gray-400);
}

.footer__grid {
  display: grid;
  grid-template-columns: 2fr repeat(4, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer__brand p { font-size: 0.9375rem; margin-top: 16px; line-height: 1.7; }

.footer__col h4 {
  color: var(--white);
  font-size: 0.875rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 16px;
}

.footer__link {
  display: block;
  font-size: 0.875rem;
  color: var(--gray-400);
  padding: 6px 0;
  transition: var(--transition);
}

.footer__link:hover { color: var(--white); transform: translateX(4px); }

.footer__bottom {
  border-top: 1px solid var(--gray-700);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8125rem;
}

@media (max-width: 900px) {
  .footer__grid { grid-template-columns: repeat(2, 1fr); }
  .footer__brand { grid-column: 1 / -1; }
}

@media (max-width: 600px) {
  .footer__grid { grid-template-columns: 1fr; }
  .footer__bottom { flex-direction: column; gap: 12px; text-align: center; }
}

/* --- Page Hero (Subpages) --- */
.page-hero {
  padding: 140px 0 64px;
  background: var(--black);
  position: relative;
  overflow: hidden;
}

.page-hero::before {
  content: '';
  position: absolute;
  top: -30%;
  right: -10%;
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, rgba(230,255,50,0.1) 0%, transparent 70%);
  pointer-events: none;
}

.page-hero h1 { color: var(--white); margin-bottom: 16px; position: relative; z-index: 1; }
.page-hero p { color: var(--gray-400); font-size: 1.1875rem; max-width: 600px; position: relative; z-index: 1; }

/* --- Feature Cards --- */
.features-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
}

.feature-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); border-color: transparent; }

.feature-card__icon {
  width: 56px;
  height: 56px;
  background: var(--lime);
  border-radius: var(--radius-md);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.5rem;
  margin-bottom: 20px;
}

.feature-card h3 { margin-bottom: 12px; }
.feature-card p { font-size: 0.9375rem; }

@media (max-width: 900px) {
  .features-grid { grid-template-columns: 1fr 1fr; }
}

@media (max-width: 600px) {
  .features-grid { grid-template-columns: 1fr; }
}

/* --- Steps --- */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  position: relative;
}

.steps-grid::before {
  content: '';
  position: absolute;
  top: 40px;
  left: calc(16.67% + 20px);
  right: calc(16.67% + 20px);
  height: 2px;
  background: var(--gray-200);
}

.step-card {
  text-align: center;
  position: relative;
}

.step-card__number {
  width: 56px;
  height: 56px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--black);
  margin: 0 auto 20px;
  position: relative;
  z-index: 1;
}

.step-card h3 { margin-bottom: 8px; }
.step-card p { font-size: 0.9375rem; }

@media (max-width: 700px) {
  .steps-grid { grid-template-columns: 1fr; }
  .steps-grid::before { display: none; }
}

/* --- Spotlight Cards --- */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
}

.spotlight-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }

.spotlight-card__tag {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--burgundy);
  background: rgba(127,42,35,0.08);
  padding: 4px 12px;
  border-radius: 20px;
  margin-bottom: 16px;
}

.spotlight-card h3 { margin-bottom: 8px; }
.spotlight-card p { font-size: 0.9375rem; }

@media (max-width: 700px) {
  .spotlight-grid { grid-template-columns: 1fr; }
}

/* --- Resources --- */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.resource-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: var(--transition);
  display: flex;
  flex-direction: column;
}

.resource-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }

.resource-card__icon {
  font-size: 2rem;
  margin-bottom: 16px;
}

.resource-card h3 { margin-bottom: 8px; font-size: 1.0625rem; }
.resource-card p { font-size: 0.875rem; flex-grow: 1; }
.resource-card__link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 16px;
  font-size: 0.875rem;
  font-weight: 600;
  transition: var(--transition);
}

.resource-card__link:hover { gap: 10px; }

@media (max-width: 700px) {
  .resources-grid { grid-template-columns: 1fr; }
}

/* --- File Types --- */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 16px;
}

.file-type-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 16px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
  transition: var(--transition);
}

.file-type-item:hover { background: var(--lime); }

.file-type-item__icon { font-size: 1.25rem; }
.file-type-item span { font-size: 0.875rem; font-weight: 500; }

/* --- Tools Grid --- */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
  gap: 12px;
}

.tools-grid__item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  background: var(--gray-50);
  border-radius: var(--radius-sm);
  font-size: 0.875rem;
  font-weight: 500;
  transition: var(--transition);
}

.tools-grid__item:hover { background: var(--lime); }

.tools-grid__icon { font-size: 1rem; }

/* --- Coaching Features (4-col) --- */
.coaching-features-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

@media (max-width: 700px) {
  .coaching-features-grid { grid-template-columns: 1fr; }
}

/* --- Membership Stats --- */
.membership-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}

.membership-stat {
  text-align: center;
  padding: 32px;
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
}

.membership-stat__number {
  font-family: var(--font-heading);
  font-size: 2.5rem;
  font-weight: 800;
  color: var(--lime);
  background: var(--black);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.membership-stat__number--solid {
  color: var(--black);
  -webkit-text-fill-color: var(--black);
}

.membership-stat h4 { margin-top: 8px; margin-bottom: 8px; }
.membership-stat p { font-size: 0.875rem; }

@media (max-width: 700px) {
  .membership-stats { grid-template-columns: 1fr; }
}

/* --- Scroll Animations --- */
.animate {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.6s ease, transform 0.6s ease;
}

.animate.visible {
  opacity: 1;
  transform: translateY(0);
}

/* --- Utilities --- */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: translateY(0); }
}

.text-center { text-align: center; }
.mt-0 { margin-top: 0; }
.mt-2 { margin-top: 8px; }
.mt-4 { margin-top: 16px; }
.mt-6 { margin-top: 24px; }
.mt-8 { margin-top: 32px; }
.mb-0 { margin-bottom: 0; }
.mb-2 { margin-bottom: 8px; }
.mb-4 { margin-bottom: 16px; }
.mb-6 { margin-bottom: 24px; }
.mb-8 { margin-bottom: 32px; }

/* --- Product Demo Accordion --- */
.demo-accordion {
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.demo-accordion__toggle {
  width: 100%;
  text-align: left;
  padding: 20px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: var(--black);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--gray-50);
  transition: var(--transition);
}

.demo-accordion__toggle:hover { background: var(--gray-100); }

.demo-accordion__icon {
  transition: var(--transition);
  font-size: 1.25rem;
  color: var(--gray-500);
}

.demo-accordion.active .demo-accordion__icon { transform: rotate(180deg); }

.demo-accordion__content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s ease;
}

.demo-accordion__content-inner {
  padding: 32px;
  background: var(--gray-900);
  color: var(--white);
}

.demo-accordion__content-inner h3 { color: var(--white); margin-bottom: 12px; }
.demo-accordion__content-inner p { color: var(--gray-400); }

/* --- Business Fit --- */
.business-fit-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

@media (max-width: 700px) {
  .business-fit-grid { grid-template-columns: 1fr; }
}

/* --- Social proof section --- */
.social-proof {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  text-align: center;
}

.social-proof__item {
  padding: 24px;
  background: var(--gray-50);
  border-radius: var(--radius-md);
}

.social-proof__item h4 { color: var(--burgundy); font-size: 1.5rem; margin-bottom: 8px; }
.social-proof__item p { font-size: 0.875rem; }

@media (max-width: 700px) {
  .social-proof { grid-template-columns: 1fr; }
}

/* --- Value Proposition Cards (with number) --- */
.value-prop-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.value-prop-card {
  background: var(--white);
  border: 1px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 32px;
  position: relative;
  transition: var(--transition);
}

.value-prop-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-xl); }

.value-prop-card__number {
  font-family: var(--font-heading);
  font-size: 3rem;
  font-weight: 800;
  color: var(--lime);
  opacity: 0.4;
  position: absolute;
  top: 16px;
  right: 24px;
}

.value-prop-card h3 { margin-bottom: 12px; }
.value-prop-card p { font-size: 0.9375rem; }

@media (max-width: 700px) {
  .value-prop-grid { grid-template-columns: 1fr; }
}

/* --- Create and Sell (split layout) --- */
.split-layout {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
}

.split-layout__content h2 { margin-bottom: 16px; }
.split-layout__content p { margin-bottom: 12px; }

.split-layout__visual {
  background: var(--gray-900);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
}

@media (max-width: 900px) {
  .split-layout { grid-template-columns: 1fr; }
}

/* --- Pricing overview (memberships page) --- */
.pricing-overview {
  background: var(--gray-100);
  border-radius: var(--radius-xl);
  padding: 48px;
  text-align: center;
}

.pricing-overview__tiers {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 32px;
}

.pricing-overview__tier {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 24px 16px;
  transition: var(--transition);
}

.pricing-overview__tier:hover { box-shadow: var(--shadow-lg); }

.pricing-overview__tier h4 { margin-bottom: 4px; }
.pricing-overview__tier .price { font-family: var(--font-heading); font-size: 1.75rem; font-weight: 800; color: var(--black); }
.pricing-overview__tier .period { font-size: 0.8125rem; color: var(--gray-500); }

@media (max-width: 900px) {
  .pricing-overview__tiers { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 600px) {
  .pricing-overview__tiers { grid-template-columns: 1fr; }
  .pricing-overview { padding: 32px 16px; }
}

